// 本地图书库：开放图书导入、章节识别、精读分析、原位点词释义和学习数据备份。
NAV.splice(2,0,['library','▤','Library']);uiTranslations.set('Library','我的图书');state.library=Array.isArray(state.library)?state.library:[];
let libraryBookId=null,libraryChapterIndex=0;
const libraryText=(zh,en)=>uiLanguage==='zh'?zh:en,libraryLimit=1200000;
const openBooks=[
  {id:11,title:'Alice’s Adventures in Wonderland',author:'Lewis Carroll',level:'A2+'},{id:55,title:'The Wonderful Wizard of Oz',author:'L. Frank Baum',level:'A2+'},{id:17396,title:'The Secret Garden',author:'Frances Hodgson Burnett',level:'B1'},{id:1661,title:'The Adventures of Sherlock Holmes',author:'Arthur Conan Doyle',level:'B1'},{id:84,title:'Frankenstein',author:'Mary Shelley',level:'B2'},{id:1342,title:'Pride and Prejudice',author:'Jane Austen',level:'B2'}
];
const libraryStopWords=new Set('the a an and or but if then than to of in on at for from with by as is are was were be been being it its this that these those he she they we you i his her their our your not no do does did have has had can could would should will may might chapter said one two into out up down about after before over under very more most some any all'.split(' '));

function openBookCatalog(){return `<section class="card open-library"><div class="mini-title"><h3>${libraryText('开放图书馆','Open book library')}</h3><span>Project Gutenberg</span></div><p>${libraryText('选择一本公版英文书，系统会识别书名、作者与章节，导入后在本站精读。','Choose a public-domain book. English Lab identifies its title, author, and chapters for close reading.')}</p><div class="open-book-grid">${openBooks.map(book=>`<article><span>${book.level}</span><h4>${esc(book.title)}</h4><small>${esc(book.author)}</small><button class="secondary" data-open-book="${book.id}">${libraryText('导入并精读','Import & study')}</button></article>`).join('')}</div><p id="open-library-message" class="muted-text">${libraryText('正文由 Project Gutenberg 按需读取；同一本书不会重复导入。','Texts are loaded on demand from Project Gutenberg. A book is never imported twice.')}</p></section>`}
function libraryListPage(){const books=state.library.slice().reverse();return `<div class="content library-page">${head(libraryText('个人阅读库','MY LIBRARY'),libraryText('选择图书或导入自己的材料','Choose a book or import your own text'),libraryText('开放图书和手动导入都会在当前页面阅读。','Open books and your own texts are read on this page.'),`<span class="pill">${books.length} ${libraryText('本资料','items')}</span>`)}${openBookCatalog()}<div class="library-grid"><section class="card library-import"><div class="eyebrow">${libraryText('手动添加','MANUAL IMPORT')}</div><label for="library-title">${libraryText('标题','Title')}</label><input id="library-title" class="input" maxlength="160" placeholder="${libraryText('例如：我的英文文章','For example: My English article')}"><label for="library-content">${libraryText('英文正文','English text')}</label><textarea id="library-content" class="input" rows="10" maxlength="${libraryLimit}" placeholder="${libraryText('粘贴英文文章，或选择 TXT / Markdown 文件……','Paste English text, or choose a TXT / Markdown file…')}"></textarea><div class="action-row"><button class="primary" id="library-add">${libraryText('识别并保存','Identify & save')}</button><label class="secondary file-button">${libraryText('选择文件','Choose file')}<input id="library-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label></div><p id="library-message" class="muted-text">${libraryText('系统会自动识别章节并生成精读数据。单篇最多约 120 万字符。','Chapters and close-reading data are detected automatically. Up to 1.2 million characters.')}</p></section><section class="card"><div class="mini-title"><h3>${libraryText('我的资料','My reading')}</h3><span>${books.length}</span></div>${books.length?`<div class="library-list">${books.map(book=>{const chapters=splitLibraryChapters(book.content);return `<article><button data-library-open="${esc(book.id)}"><b>${esc(book.title)}</b><small>${esc(book.author||libraryText('手动导入','Manual import'))} · ${chapters.length} ${libraryText('章','chapters')} · ${book.finished?libraryText('已读完','Finished'):libraryText('阅读中','Reading')}</small></button><button class="library-delete" data-library-delete="${esc(book.id)}" aria-label="${libraryText('删除','Delete')} ${esc(book.title)}">×</button></article>`}).join('')}</div>`:`<div class="library-empty"><b>${libraryText('图书库还是空的','Your library is empty')}</b><p>${libraryText('可以从上方开放图书馆选择，也可以手动导入。','Choose from the open library or import your own text.')}</p></div>`}</section></div><section class="card library-backup"><div><div class="eyebrow">${libraryText('数据安全','DATA BACKUP')}</div><h3>${libraryText('备份全部学习记录','Back up all learning data')}</h3><p>${libraryText('导出单词进度、阅读记录、笔记和本地图书。','Export vocabulary, reading, notes, and local books.')}</p></div><div class="action-row"><button class="secondary" id="data-export">${libraryText('导出 JSON 备份','Export JSON')}</button><label class="secondary file-button">${libraryText('恢复备份','Restore backup')}<input id="data-import" type="file" accept="application/json,.json"></label></div></section></div>`}

function splitLibraryChapters(content){
  const text=String(content||'').replace(/\r\n/g,'\n').trim(),pattern=/^(?:chapter\s+(?:[ivxlcdm]+|\d+|one|two|three|four|five|six|seven|eight|nine|ten)\b.*|book\s+(?:[ivxlcdm]+|\d+)\b.*|part\s+(?:[ivxlcdm]+|\d+)\b.*)$/gim,matches=[...text.matchAll(pattern)];
  if(matches.length>=2){const chapters=[];if(matches[0].index>200)chapters.push({title:libraryText('序言','Preface'),content:text.slice(0,matches[0].index).trim()});matches.forEach((match,index)=>{const end=matches[index+1]?.index||text.length;chapters.push({title:match[0].trim(),content:text.slice(match.index,end).trim()})});return chapters.filter(item=>item.content.length>80)}
  if(text.length<=24000)return [{title:libraryText('全文','Full text'),content:text}];
  const paragraphs=text.split(/\n\s*\n/),chapters=[];let current=[];for(const paragraph of paragraphs){current.push(paragraph);if(current.join('\n\n').length>=18000){chapters.push({title:`${libraryText('阅读单元','Reading unit')} ${chapters.length+1}`,content:current.join('\n\n')});current=[]}}if(current.length)chapters.push({title:`${libraryText('阅读单元','Reading unit')} ${chapters.length+1}`,content:current.join('\n\n')});return chapters;
}
function libraryWordInfo(name){const lower=name.toLowerCase().replace(/^'+|'+$/g,''),forms=[lower,lower.replace(/'s$/,''),lower.replace(/ies$/,'y'),lower.replace(/s$/,''),lower.replace(/ing$/,''),lower.replace(/ed$/,'')];return WORDS.find(item=>forms.includes(item.w))||null}
function analyzeLibraryChapter(chapter){const words=(chapter.content.match(/[A-Za-z][A-Za-z'-]*/g)||[]),sentences=chapter.content.split(/[.!?]+/).filter(item=>item.trim().length>8),frequency=new Map();for(const raw of words){const name=raw.toLowerCase();if(name.length<3||libraryStopWords.has(name))continue;frequency.set(name,(frequency.get(name)||0)+1)}const keyWords=[...frequency].sort((a,b)=>b[1]-a[1]).map(([name,count])=>({name,count,entry:libraryWordInfo(name)})).filter(item=>item.entry).slice(0,8);const average=sentences.length?Math.round(words.length/sentences.length):0,level=average<12?'A2':average<18?'B1':'B2+';return {words:words.length,sentences:sentences.length,average,level,keyWords,minutes:Math.max(1,Math.ceil(words.length/160))}}
function renderLibraryMeaning(name){const item=libraryWordInfo(name);if(!item)return `<div class="inline-word-empty"><b>${esc(name)}</b><p>${libraryText('当前本地 ECDICT 学习词库暂未收录这个词。','This word is not in the local ECDICT learning set yet.')}</p></div>`;return `<div class="inline-word-result"><div><h3>${esc(item.w)}</h3><button class="secondary" data-speak="${esc(item.w)}">🔊</button></div><p class="phonetic">${esc(item.ipa||'')}</p><strong>${esc(item.zh)}</strong>${item.ex?`<p>${esc(item.ex)}</p>`:''}<button class="dict-study" data-learn-word="${esc(item.w)}">${libraryText('加入学习词汇','Add to study words')}</button></div>`}
function libraryReaderPage(){
  const book=state.library.find(item=>item.id===libraryBookId);if(!book)return libraryListPage();const chapters=splitLibraryChapters(book.content);libraryChapterIndex=Math.min(Math.max(0,libraryChapterIndex),chapters.length-1);const chapter=chapters[libraryChapterIndex],analysis=analyzeLibraryChapter(chapter),finishedChapters=Array.isArray(book.finishedChapters)?book.finishedChapters:[];
  const paragraphs=chapter.content.split(/\n\s*\n/).filter(Boolean).map(paragraph=>`<p>${esc(paragraph).replace(/\b([A-Za-z][A-Za-z'-]{1,})\b/g,'<button data-library-lookup="$1">$1</button>').replace(/\n/g,'<br>')}</p>`).join('');
  return `<div class="content library-reader">${head(libraryText('图书精读','BOOK STUDY'),esc(book.title),`${esc(book.author||libraryText('作者未识别','Unknown author'))} · ${chapters.length} ${libraryText('个章节','chapters')}`,`<span class="pill">${libraryChapterIndex+1} / ${chapters.length}</span>`)}<div class="reader-actions"><button class="secondary" data-nav="library">← ${libraryText('返回图书库','Back')}</button><select id="library-chapter" class="input" aria-label="${libraryText('选择章节','Choose chapter')}">${chapters.map((item,index)=>`<option value="${index}" ${index===libraryChapterIndex?'selected':''}>${index+1}. ${esc(item.title.slice(0,80))}</option>`).join('')}</select><button class="secondary" id="library-prev" ${libraryChapterIndex===0?'disabled':''}>← ${libraryText('上一章','Previous')}</button><button class="secondary" id="library-next" ${libraryChapterIndex===chapters.length-1?'disabled':''}>${libraryText('下一章','Next')} →</button><button class="primary" id="library-finish-chapter">${finishedChapters.includes(libraryChapterIndex)?'✓ '+libraryText('本章已完成','Chapter complete'):libraryText('标记本章完成','Complete chapter')}</button><button class="secondary" id="print">${libraryText('打印／保存 PDF','Print / Save PDF')}</button></div><div class="book-study-grid"><article class="card imported-reading"><h2>${esc(chapter.title)}</h2>${paragraphs}</article><aside class="book-study-side"><section class="card close-reading"><div class="mini-title"><h3>${libraryText('精读解析','Close reading')}</h3><span>${analysis.level}</span></div><div class="analysis-stats"><div><b>${analysis.words}</b><small>${libraryText('词','words')}</small></div><div><b>${analysis.sentences}</b><small>${libraryText('句','sentences')}</small></div><div><b>${analysis.minutes}</b><small>${libraryText('分钟','min')}</small></div></div><p>${libraryText(`平均每句约 ${analysis.average} 词。先通读一段，再点不熟悉的词查看单一释义。`,`About ${analysis.average} words per sentence. Read a paragraph first, then tap unfamiliar words.`)}</p><h4>${libraryText('本章重点词','Chapter key words')}</h4><div class="chapter-keywords">${analysis.keyWords.map(item=>`<button data-library-lookup="${esc(item.name)}">${esc(item.name)} <small>×${item.count}</small></button>`).join('')||libraryText('本章暂无可匹配的重点词。','No matched key words in this chapter.')}</div></section><section class="card inline-dictionary"><div class="mini-title"><h3>${libraryText('点词释义','Tap-word meaning')}</h3><span>ECDICT</span></div><div id="library-word-result"><p class="muted-text">${libraryText('点击正文中的任意英文单词，这里只显示该单词的汉语意思。','Tap a word in the text to show only that word’s Chinese meaning here.')}</p></div></section></aside></div><p class="footer-note">${libraryText('正文保存在当前浏览器；章节识别与精读统计在本地完成。','The text stays in this browser; chapter detection and reading analysis run locally.')}</p></div>`;
}

const renderBeforeLibrary=render;render=function(){renderBeforeLibrary();if(page==='library'){$('#app').innerHTML=libraryListPage();localizePage()}if(page==='library-reader'){$('#app').innerHTML=libraryReaderPage();localizePage();document.title=`English Lab · ${libraryText('图书精读','Book study')}`}};
function addLibraryBook(title,content,meta={}){const clean=String(content||'').replace(/\r\n/g,'\n').trim();if(!clean){toast(libraryText('没有读取到英文正文','No English text was found'));return false}if(clean.length>libraryLimit){toast(libraryText('图书超过 120 万字符，请拆分后导入','This book is over 1.2 million characters; split it first'));return false}const duplicate=state.library.find(item=>(meta.sourceId&&item.sourceId===meta.sourceId)||item.title===title);if(duplicate){libraryBookId=duplicate.id;libraryChapterIndex=duplicate.chapterIndex||0;page='library-reader';toast(libraryText('这本书已经在图书库中','This book is already in your library'));render();return true}const item={id:crypto.randomUUID?.()||`book-${Date.now()}`,title:(title||clean.split('\n')[0]||libraryText('未命名文章','Untitled')).slice(0,160),author:meta.author||'',source:meta.source||'local',sourceId:meta.sourceId||'',content:clean,createdAt:today(),finished:false,finishedChapters:[],chapterIndex:0};state.library.push(item);try{save()}catch{state.library.pop();toast(libraryText('浏览器存储空间不足，请先导出备份并删除不用的图书','Browser storage is full. Back up and remove unused books first.'));return false}libraryBookId=item.id;libraryChapterIndex=0;page='library-reader';render();return true}
function downloadJson(){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify({format:'english-lab-backup',version:2,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}));link.download=`English-Lab-Backup-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}

document.addEventListener('change',async changeEvent=>{if(changeEvent.target.id==='library-file'){const file=changeEvent.target.files?.[0];if(!file)return;if(file.size>libraryLimit*2){toast(libraryText('文件过大，请拆分后导入','File too large'));changeEvent.target.value='';return}const content=await file.text();$('#library-title').value=file.name.replace(/\.(txt|md)$/i,'');$('#library-content').value=content.slice(0,libraryLimit);$('#library-message').textContent=libraryText('文件已读取，点击“识别并保存”。','File loaded. Click Identify & save.');changeEvent.target.value=''}if(changeEvent.target.id==='library-chapter'){libraryChapterIndex=Number(changeEvent.target.value)||0;const book=state.library.find(item=>item.id===libraryBookId);if(book){book.chapterIndex=libraryChapterIndex;save()}render();window.scrollTo(0,0)}if(changeEvent.target.id==='data-import'){const file=changeEvent.target.files?.[0];if(!file)return;try{const backup=JSON.parse(await file.text());if(backup?.format!=='english-lab-backup'||!backup.state)throw new Error();state={...state,...backup.state,reviews:{...state.reviews,...backup.state.reviews},learned:[...new Set([...(state.learned||[]),...(backup.state.learned||[])])],library:[...(state.library||[]),...(backup.state.library||[])]};save();toast(libraryText('备份已恢复','Backup restored'));render()}catch{toast(libraryText('备份文件无效','Invalid backup'))}changeEvent.target.value=''}},true);
document.addEventListener('click',async clickEvent=>{const button=clickEvent.target.closest('button');if(!button)return;if(button.id==='library-add'&&page==='library'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();addLibraryBook($('#library-title').value.trim(),$('#library-content').value);return}if(button.dataset.openBook&&page==='library'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();button.disabled=true;button.textContent=libraryText('正在导入……','Importing…');const message=$('#open-library-message');message.textContent=libraryText('正在读取并识别图书，请稍候……','Loading and identifying the book…');try{const response=await fetch('/api/books/'+button.dataset.openBook),data=await response.json();if(!response.ok)throw new Error(data.error||libraryText('导入失败','Import failed'));addLibraryBook(data.title,data.content,{author:data.author,source:data.source,sourceId:String(data.id)})}catch(error){message.textContent=`${libraryText('导入失败：','Import failed: ')}${error.message}`;button.disabled=false;button.textContent=libraryText('重试导入','Try again')}return}if(button.dataset.libraryOpen){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();const book=state.library.find(item=>item.id===button.dataset.libraryOpen);libraryBookId=button.dataset.libraryOpen;libraryChapterIndex=book?.chapterIndex||0;page='library-reader';render();return}if(button.dataset.libraryLookup&&page==='library-reader'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();const target=$('#library-word-result');if(target)target.innerHTML=renderLibraryMeaning(button.dataset.libraryLookup);return}if(button.dataset.libraryDelete){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();if(confirm(libraryText('确定删除这本本地图书吗？','Delete this local book?'))){state.library=state.library.filter(item=>item.id!==button.dataset.libraryDelete);save();render()}return}if(button.id==='library-prev'||button.id==='library-next'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();libraryChapterIndex+=button.id==='library-next'?1:-1;const book=state.library.find(item=>item.id===libraryBookId);if(book){book.chapterIndex=libraryChapterIndex;save()}render();window.scrollTo(0,0);return}if(button.id==='library-finish-chapter'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();const book=state.library.find(item=>item.id===libraryBookId);if(book){book.finishedChapters=Array.isArray(book.finishedChapters)?book.finishedChapters:[];if(!book.finishedChapters.includes(libraryChapterIndex))book.finishedChapters.push(libraryChapterIndex);const count=splitLibraryChapters(book.content).length;book.finished=book.finishedChapters.length>=count;event('read',`library:${book.id}:${libraryChapterIndex}`);save();toast(libraryText('本章阅读已记录','Chapter recorded'));if(libraryChapterIndex<count-1){libraryChapterIndex++;book.chapterIndex=libraryChapterIndex;save()}render()}return}if(button.id==='data-export'&&page==='library'){clickEvent.preventDefault();clickEvent.stopImmediatePropagation();downloadJson()}},true);
render();
